I'm trying to access metric related information (i.e. lower_bounds, upper_bounds, distinct_counts) for each Data File after performing a scan using the Java API. I've confirmed (by looking in the manifest files) that these pieces of metadata are written. However, the Java API says that all of these values are null for some reason.
Minimal Reproducer:
Spark Code to Generate the Tables:
from datetime import datetime
import numpy as np
import pandas as pd
import pyspark.sql.types as spark_types

def create_table(table_name="test_table"):
    spark = (
        SparkSession.builder.appName("Iceberg with Spark")
        .config(
            "spark.jars.packages",
            "org.apache.iceberg:iceberg-spark-runtime-3.2_2.12:0.13.0",
        )
        .config("spark.sql.catalog.hadoop_prod", "org.apache.iceberg.spark.SparkCatalog")
        .config("spark.sql.catalog.hadoop_prod.type", "hadoop")
        .config("spark.sql.catalog.hadoop_prod.warehouse", ".")
        .config(
            "spark.sql.extensions",
            "org.apache.iceberg.spark.extensions.IcebergSparkSessionExtensions",
        )
        .getOrCreate()
    )

    df = pd.DataFrame(
        {
            "index": np.arange(25, dtype=np.int32),
            "dates": pd.Series([datetime.strptime(f"12/11/{2010 + x}", "%d/%m/%Y") for x in range(25)]),
        }
    )

    schema = spark_types.StructType(
        [
            spark_types.StructField("index", spark_types.IntegerType(), False),
            spark_types.StructField("dates",  spark_types.DateType(), False),
        ]
    )

    df = spark.createDataFrame(df, schema=schema)
    df.writeTo(f"hadoop_prod.iceberg_db.{table_name}").tableProperty(
        "format-version", "2"
    ).tableProperty("write.delete.mode", "merge-on-read").createOrReplace()

if __name__ == "__main__":
    create_table()
